1	import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';
2	const base=path.resolve('acceptance/20261024-long-flow-090-ac'),get=p=>JSON.parse(fs.readFileSync(p)),cp=get(path.join(base,'checkpoint-d-first.json')),root=cp.project,sha=b=>crypto.createHash('sha256').update(b).digest('hex'),b=fs.readFileSync(path.join(root,'.writer/state.json')),state=JSON.parse(b),status=get(path.join(base,'cli-logs/dr01-status/stdout.txt')),doctor=get(path.join(base,'cli-logs/dr03-doctor/stdout.txt'));
3	assert.equal(process.env.CODEX_THREAD_ID,cp.thread_id);assert.equal(sha(b),cp.state_sha256);assert.deepEqual(state,get(path.join(base,'checkpoint-d-first-state.json')));assert.equal(state.revision,211);assert.equal(state.units.length,46);assert.equal(state.units.at(-1).sha256,cp.chapter46.sha256);for(const [ref,expected] of Object.entries(cp.files)){const bytes=fs.readFileSync(path.join(root,ref));assert.equal(bytes.length,expected.bytes,ref);assert.equal(sha(bytes),expected.sha256,ref);}for(const key of ['stale_units','changed_sources','impact_pending'])assert.deepEqual(status[key],[]);assert.equal(status.tool_control.generation,6);assert.equal(doctor.build.observed_content_id,cp.content_id);assert.equal(doctor.build.runtime_id,cp.runtime_id);assert.deepEqual(doctor.errors,[]);assert.deepEqual(doctor.warnings,[]);assert(status.revisions.sessions.every(s=>s.status==='committed'));assert(status.revisions.transactions.every(t=>t.status==='completed'));assert.deepEqual(status.draft_inventory.unregistered.map(x=>x.draft).sort(),[...cp.known_unregistered_drafts].sort());
4	const template=get(path.join(root,cp.chapter47.template.ref));assert.equal(template.expected_revision,211);assert.equal(sha(fs.readFileSync(path.join(root,cp.chapter47.template.ref))),cp.chapter47.template.sha256);assert.equal(sha(fs.readFileSync(path.join(root,cp.chapter47.context.ref))),cp.chapter47.context.sha256);for(const [ref,h] of Object.entries(template.source_hashes))assert.equal(sha(fs.readFileSync(path.join(root,ref))),h,ref);for(const part of cp.chapter47.parts){const bytes=fs.readFileSync(path.join(root,part.ref));assert.equal(sha(bytes),part.sha256);fs.writeFileSync(path.join(base,'dr-inputs/47-original-'+path.basename(part.ref)),bytes,{flag:'wx'});}
5	const actualOldFailures=['d16-assemble46-final','d18-assemble46-new-target'].map(label=>({label,...get(path.join(base,'cli-logs',label,'result.json'))}));
6	const result={ok:true,at:new Date().toISOString(),thread_id:process.env.CODEX_THREAD_ID,revision:211,registered_units:46,state_sha256:sha(b),checkpoint_fully_parsed:true,checkpoint_files_matched:Object.keys(cp.files).length,template47_original_sha256:cp.chapter47.template.sha256,context47_original_sha256:cp.chapter47.context.sha256,parts47_original:cp.chapter47.parts,source_hashes_matched:true,generation:6,content_id:cp.content_id,runtime_id:cp.runtime_id,unknown_drafts:[],pending_transactions:[],old_failure_exit_codes:actualOldFailures.map(x=>({label:x.label,product_exit_code:x.exit_code,state_unchanged:x.before_state_sha256===x.after_state_sha256})),note:'首停文字把两次产品拒绝写成退出1；result.json实际产品退出2。外层PowerShell退出1，完成交接更正口径，旧证据不回写。'};
7	fs.writeFileSync(path.join(base,'dr-inputs/resume-verification.json'),JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(result,null,2));
8	

